/**
 * Scenario registry. Every scenario is addressable by id, and generated ones are rebuilt
 * deterministically from their id, so a phone remote only has to send an id string.
 *
 *   fixture ids        scn-riser-leak, scn-gen-nostart, scn-chiller-trip   (src/domain/fixture.ts)
 *   real-incident ids  real-*   adapted from public post-incident reports, compressed, simulated
 *   random ids         rnd-<seed>  generated by randomScenario(id)
 *
 * CONTRACT: other code calls getScenario / listScenarios / randomScenarioId / isRandomScenario,
 * and incidentsFor(scenario, run) for the incidents the engine raises.
 */
import { scenarios as fixtureScenarios } from '../fixture';
import type { ScenarioRun } from '../engine/simulate';
import type { Incident, Scenario } from '../types';
import { randomScenario } from './random';
import { realScenarios } from './real';

export { randomScenario, generateRandomScenario, TEMPLATES, seedOf } from './random';
export type { TemplateKey } from './random';
export { realScenarios } from './real';

export interface ScenarioInfo { id: string; name: string; kind: NonNullable<Scenario['kind']>; headline: string; basis: string }

const byId = new Map<string, Scenario>([...fixtureScenarios, ...realScenarios].map((s) => [s.id, s]));

/** Any scenario id → Scenario. Unknown ids fall back to the first fixture scenario. */
export function getScenario(id: string): Scenario {
  if (isRandomScenario(id)) return randomScenario(id);
  return byId.get(id) ?? fixtureScenarios[0];
}

/** Scenarios a presenter can pick from a list: the default demo first, then real incidents, then what-ifs. */
export function listScenarios(): ScenarioInfo[] {
  const rank = (s: Scenario) => (s.id === fixtureScenarios[0].id ? 0 : s.kind === 'real' ? 1 : 2);
  return [...byId.values()]
    .sort((a, b) => rank(a) - rank(b))
    .map((s) => ({ id: s.id, name: s.name, kind: s.kind ?? 'what-if', headline: s.headline ?? s.name, basis: s.basis }));
}

/** A fresh random-disaster id (the caller sends it through the stage). */
export function randomScenarioId(rand: () => number = Math.random): string {
  return `rnd-${Math.floor(rand() * 1e9).toString(36)}`;
}

export const isRandomScenario = (id: string) => id.startsWith('rnd-');

/**
 * Incidents the engine raises during a run, each opened when the clock passes `openedAt`.
 * Static ones come from `scenario.incidents`. For scenarios with a leak, the water-exposure
 * incident is rebuilt from the run: it follows fixes (isolate the leak early and it never opens).
 */
export function incidentsFor(scenario: Scenario, run: ScenarioRun): Incident[] {
  const list = scenario.incidents ?? [];
  if (!scenario.leak) return list;
  const wet = Object.entries(run.waterArrival).filter(([, t]) => t <= scenario.horizonMin).sort((a, b) => a[1] - b[1]);
  const wetIds = wet.map(([id]) => id);
  const power = wet.filter(([id]) => /^(UPS|BATT|ATS|PDU)/.test(id));
  const out: Incident[] = [];
  for (const inc of list) {
    if (inc.id === 'INC-1044') { out.push({ ...inc, alertAssetIds: ['PIPE-L2', ...wetIds] }); continue; }
    if (inc.id === 'INC-1045') {
      if (!power.length) continue; // the water never reaches power equipment in this run
      const [first, t] = power[0];
      out.push({ ...inc, title: `Water reached ${first} — battery/UPS exposure`, rootAssetId: first, alertAssetIds: power.map(([id]) => id), openedAt: Math.max(12, Math.ceil(t)) });
      continue;
    }
    out.push(inc);
  }
  // generated / real leak scenarios without a hand-written exposure incident get one
  if (scenario.id !== 'scn-riser-leak' && power.length && !list.some((i) => i.id.endsWith('-W'))) {
    const [first, t] = power[0];
    out.push({
      id: `INC-${scenario.id.slice(-4).toUpperCase()}-W`, title: `Water reached ${first} — power equipment exposed`, rootAssetId: first,
      alertAssetIds: power.map(([id]) => id), severity: 'critical', status: 'open', evidence: 'unverified', shiftLeadId: 'emp-priya',
      openedAt: Math.ceil(t), summary: 'The water layer (approximation) shows the wet front at UPS / battery / distribution equipment.',
      recentChanges: [], runbookId: 'RB-BATT',
    });
  }
  return out.sort((a, b) => a.openedAt - b.openedAt);
}
